namespace speed {
namespace {
const DracoRiftsDefinition &rule(const RunRuntime &r,const TechniqueState &t) {return *std::find_if(r.content->draco_rifts.begin(),r.content->draco_rifts.end(),[&](const auto &v){return v.technique==t.definition;});}
HazardState *owned(RunRuntime &r,EnemyHandle actor,AttackHandle attack) {const auto *record=AttackSystem::get(r.state,attack);if (!record || record->pool!=AttackPool::Hazard || !same_handle(record->spec.owner.live_source,actor) || !std::holds_alternative<WallHazard>(r.state.hazards[record->row].shape)) return nullptr;return &r.state.hazards[record->row];}
void lock(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoRiftsState>(v.move);const auto &b=*PhaseController::find(r,t.actor);const auto &e=r.state.enemies[t.actor.slot];const auto &d=rule(r,t);const auto &p=r.content->boss_techniques[t.definition-1];s.center=DracoTechnique::predict(r,t.actor,0,DracoBody::rule(r,b).aim_lead_cap);auto forward=(s.center-e.pos).normalized();if (forward.is_zero_approx()) forward=godot::Vector2(-s.staging.side,0);const auto lateral=forward.orthogonal();t.direction=forward;s.claws=std::max(1u,d.claw_count);const double start=125*b.draco.head_scale,length=std::min(p.reach,double((s.center-e.pos).dot(forward))+d.claw_overshoot-start);for (int side:{-1,1}) for (uint32_t j=0;j<s.claws;++j) {const double stripe=side*d.claw_offset+(double(j)-(double(s.claws)-1)*0.5)*d.claw_gap;const auto from=e.pos+forward*start+lateral*stripe,to=from+forward.rotated(-side*d.claw_angle)*std::max(1.0,length);s.paths.push_back({from,to});v.warning_paths.push_back(s.paths.back());}v.warning_width=d.scratch_width*0.5;t.locked=true;}
void close(RunRuntime &r,BossBodyState &b,AttackHandle attack,double delay) {auto *h=owned(r,b.actor,attack);if (!h) return;h->damage=0;const auto &w=std::get<WallHazard>(h->shape);DracoClosingWall wall;wall.attack=attack;wall.from=h->pos;wall.length=w.length;wall.half_width=w.half_width;wall.angle=w.angle;wall.delay=delay;b.draco.closing_walls.push_back(wall);}
}
void DracoRifts::begin(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);v.move=DracoRiftsState{};auto &s=std::get<DracoRiftsState>(v.move);s.center=DracoTechnique::predict(r,t.actor,0,DracoBody::rule(r,*PhaseController::find(r,t.actor)).aim_lead_cap);DracoScreenStaging::begin(r,t,s.staging,true);}
void DracoRifts::windup(RunRuntime &r,TechniqueState &t,double dt) {auto &s=std::get<DracoRiftsState>(std::get<DracoTechniqueState>(t.detail).move);if (!DracoScreenStaging::advance(r,t,s.staging,dt)) return;if (!t.locked) lock(r,t);auto &e=r.state.enemies[t.actor.slot];e.facing+=angle_difference(t.direction.angle()-e.facing)*std::clamp(dt*9,0.0,1.0);}
void DracoRifts::active(RunRuntime &r,TechniqueState &t) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoRiftsState>(v.move);const auto &p=r.content->boss_techniques[t.definition-1];const auto &d=rule(r,t);const auto ticket=r.state.bosses->handles.at(uint32_t(&t-r.state.bosses->techniques.data()));while (s.sides<2 && v.stage_time>=s.sides*d.interval) {for (uint32_t j=0;j<s.claws;++j) {const auto &points=s.paths[s.sides*s.claws+j];const auto delta=points[1]-points[0];WallParams wall;wall.position=points[0];wall.angle=delta.angle();wall.length=1;wall.half_width=d.scratch_width*0.5;wall.active=d.scratch_time;wall.damage=p.damage*r.state.combat_config.atk_scale;wall.color=godot::Color::html("e4cfff");wall.owner=t.actor;wall.attached=true;wall.technique=ticket;s.slashes.push_back(WallSystem::emit(r,wall));wall.half_width=p.width*0.5;wall.active=p.active+p.recover+1;wall.damage=0;wall.color=godot::Color::html("34224d");wall.blocking=true;wall.style=WallStyle::Trail;s.walls.push_back(WallSystem::emit(r,wall));}++s.sides;}
    v.warning_paths.clear();for (size_t index=0;index<s.paths.size();++index) {const double local=v.stage_time-double(index/s.claws)*d.interval;const auto &path=s.paths[index];if (local<0) {v.warning_paths.push_back(path);continue;}const auto tip=path[0].lerp(path[1],std::clamp(local/d.scratch_time,0.0,1.0)),delta=tip-path[0];if (index<s.slashes.size() && owned(r,t.actor,s.slashes[index])) WallSystem::move(r,s.slashes[index],path[0],delta.angle(),std::max(1.0,double(delta.length())));if (index<s.walls.size() && owned(r,t.actor,s.walls[index])) {WallSystem::move(r,s.walls[index],path[0],delta.angle(),std::max(1.0,double(delta.length())));const auto span=tip-path[0];const double f=span.length_squared()>0?std::clamp(double((r.state.ship_pos-path[0]).dot(span))/span.length_squared(),0.0,1.0):0;const auto nearest=path[0]+span*f,away=r.state.ship_pos-nearest;const double margin=r.state.ship_config.ship_radius+p.width*0.5+1;if (away.length()<margin) {r.state.ship_pos=nearest+(away.length()>0.01?away.normalized():delta.normalized().orthogonal())*margin;r.state.ship.pos=r.state.ship_pos;}}}
}
void DracoRifts::end(RunRuntime &r,TechniqueState &t,bool cancelled) {auto &v=std::get<DracoTechniqueState>(t.detail);auto &s=std::get<DracoRiftsState>(v.move);auto *b=PhaseController::find(r,t.actor);if (!b) return;if (cancelled) DracoPose::reset(r,*b);if (s.ended) {if (cancelled) for (auto &wall:b->draco.closing_walls) for (auto h:s.walls) if (same_handle(h,wall.attack)) wall.delay=0;return;}s.ended=true;for (auto h:s.slashes) if (owned(r,t.actor,h)) AttackSystem::end(r.state,h,cancelled?AttackEndReason::TechniqueCancel:AttackEndReason::TechniqueEnd);for (auto h:s.walls) close(r,*b,h,cancelled?0:r.content->boss_techniques[t.definition-1].recover);v.warning_paths.clear();}
void DracoRifts::tick_closing(RunRuntime &r,BossBodyState &b,double dt) {auto &walls=b.draco.closing_walls;for (auto i=walls.begin();i!=walls.end();) {if (i->delay>0) {i->delay=std::max(0.0,i->delay-dt);++i;continue;}i->time-=dt;auto *h=owned(r,b.actor,i->attack);if (!h || i->time<=0) {if (h) AttackSystem::end(r.state,i->attack,AttackEndReason::TechniqueEnd);i=walls.erase(i);continue;}const double f=i->time/i->duration;auto &w=std::get<WallHazard>(h->shape);w.length=i->length*f;w.half_width=i->half_width*f;h->pos=i->from+godot::Vector2::from_angle(i->angle)*i->length*(1-f)*0.5;++i;}}
void DracoRifts::clear(RunRuntime &r,BossBodyState &b) {for (const auto &h:r.state.hazards) {if (!h.alive) continue;const auto *a=AttackSystem::get(r.state,h.attack);if (a && same_handle(a->spec.owner.live_source,b.actor) && a->spec.source_technique && r.content->boss_techniques[a->spec.source_technique-1].kind==104) AttackSystem::end(r.state,h.attack,AttackEndReason::ParticipantEnd);}b.draco.closing_walls.clear();}
bool DracoRifts::validate(const DracoRiftsState &s) {if (!s.center.is_finite() || s.claws<1 || s.claws>2048 || s.sides>2 || !DracoScreenStaging::validate(s.staging) || (!s.paths.empty() && s.paths.size()!=s.claws*2) || s.walls.size()!=s.sides*s.claws || s.slashes.size()!=s.walls.size()) return false;for (const auto &path:s.paths) {if (path.size()!=2) return false;for (auto p:path) if (!p.is_finite()) return false;}return true;}
bool DracoRifts::validate_body(const DracoBodyState &s) {for (const auto &w:s.closing_walls) {if (!w.from.is_finite()) return false;for (double v:{w.time,w.duration,w.delay,w.length,w.half_width,w.angle}) if (!std::isfinite(v)) return false;if (w.time<=0 || w.duration<=0 || w.delay<0 || w.length<0 || w.half_width<0) return false;}return true;}
godot::Dictionary DracoRifts::snapshot(const TechniqueState &t) {const auto &s=std::get<DracoRiftsState>(std::get<DracoTechniqueState>(t.detail).move);godot::Dictionary out;out["staging_ready"]=s.staging.phase==2;out["staging_phase"]=s.staging.phase;out["staging_side"]=s.staging.side;out["exit_time"]=s.staging.exit_time;out["entry_time"]=s.staging.entry_time;out["sides"]=s.sides;out["wall_count"]=int64_t(s.walls.size());out["ended"]=s.ended;godot::Array paths;for (const auto &p:s.paths) {godot::PackedVector2Array path;for (auto point:p) path.push_back(point);paths.push_back(path);}out["rift_paths"]=paths;return out;}
void DracoRifts::snapshot_body(const RunRuntime &r,const BossBodyState &b,godot::Dictionary &out) {godot::Array walls;for (const auto &h:r.state.hazards) {if (!h.alive) continue;const auto *w=std::get_if<WallHazard>(&h.shape);const auto *a=AttackSystem::get(r.state,h.attack);if (!w || !w->blocking || !a || !same_handle(a->spec.owner.live_source,b.actor) || !a->spec.source_technique || r.content->boss_techniques[a->spec.source_technique-1].kind!=104) continue;godot::Dictionary v;v["position"]=h.pos;v["angle"]=w->angle;v["length"]=w->length;v["width"]=w->half_width*2;v["index"]=a->row;walls.push_back(v);}out["rift_walls"]=walls;out["closing_walls"]=int64_t(b.draco.closing_walls.size());}
}
